// --------------------------------------------------
// 主逻辑
// --------------------------------------------------
// 五轴使能由 AxisEnableControl_PRG 根据 arReg_data[32] 统一控制。
// 这里不再每周期强制 TRUE，避免覆盖寄存器关闭使能命令。
arAi_data[9]:=bfiveDOF_state;
// 检测外部移动指令
trig_start(CLK := Move_5Axis_Sign=1);
IF trig_start.Q THEN

	log_msg := 'five-axis platform starts moving';
// 	logfb(write:=TRUE,sFileTestString:=log_msg);
	AppendLog(log_msg);

    // 使能所有轴（可放在这里一次性使能）
	bfiveDOF_state:=1;//开始运动
    AppendLog('status 0:6-axis start move' );
    step := 10;   // 开始安全顺序
END_IF

CASE step OF
    0: // 空闲
		bfiveDOF_state:=0;//开始运动
    // ---------- 阶段1：轴移动到目标 ----------
    10:
		FOR i := 1 TO AXIS_COUNT DO
			final_angle[i] := PlatformTargetAngle[i];
			final_vel[i]   := 360*6000/60;
			Axes[i].AxisDone := FALSE;  
			GVL.Axes[i].NeedMoveAxis := TRUE;
		END_FOR
        fbMove_2(AxisAngle := final_angle, AxisVel := final_vel, Execute := TRUE,Monitor:=TRUE);
        step := 20;

		log_msg := 'State 20: Start moving XYABC AXIS... ';
// 		logfb(write:=TRUE,sFileTestString:=log_msg);
		AppendLog(log_msg);;
    20:
        fbMove_2(AxisAngle := final_angle, AxisVel := final_vel, Execute := FALSE,Monitor:=TRUE);
        IF fbMove_2.allDone THEN
			log_msg := 'State 21: XYZABC AXIS movement completed';
// 			logfb(write:=TRUE,sFileTestString:=log_msg);
			AppendLog(log_msg);
        ELSIF fbMove_2.Error THEN
            bfiveDOF_state:=2;
        END_IF
		step := 0;



END_CASE
